  insert into public.curriculum_map (course_id, plo_id, sub_plo_id, level)
  select c.id, null, sp.id, src.lvl::public.mapping_level
  from src
  join public.courses c on c.curriculum_id = v_cur and c.course_code = src.course_code
  join public.plos p on p.curriculum_id = v_cur and p.code = 'PLO' || split_part(src.sub_code, '.', 1)
  join public.sub_plos sp on sp.plo_id = p.id and sp.code = src.sub_code
  on conflict (course_id, plo_id, sub_plo_id) do update set level = excluded.level;

  get diagnostics v_n = row_count;
  if v_n <> 260 then raise exception 'คาดหวัง 260 รายการ แต่บันทึกได้ % รายการ — ตรวจสอบรหัสวิชา/sub-PLO', v_n; end if;

  update public.curriculum_mapping_staging
